import React from 'react';
import { Link } from 'react-router-dom';
import { BookOpen, CheckCircle, Code, Award } from 'lucide-react';

const Home = () => {
  return (
    <div className="flex flex-col items-center text-center space-y-12">
      <div className="max-w-3xl space-y-6">
        <h1 className="text-5xl md:text-6xl font-extrabold tracking-tight">
          Master <span className="text-primary-600">Java OOP</span> with Precision
        </h1>
        <p className="text-xl text-slate-600 dark:text-slate-400">
          The ultimate comprehensive guide to learning Object-Oriented Programming in Java.
          From basic classes to advanced Reflection API, we've got you covered with notes, MCQs, and a coding playground.
        </p>
        <div className="flex gap-4 justify-center">
          <Link to="/register" className="btn-primary px-8 py-3 text-lg">Start Learning Now</Link>
          <Link to="/login" className="px-8 py-3 text-lg font-medium hover:text-primary-600 transition-colors">Sign In</Link>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8 w-full max-w-6xl">
        <FeatureCard
          icon={<BookOpen className="text-primary-600" size={32} />}
          title="Structured Learning"
          description="14 comprehensive modules covering everything from basic OOP to advanced Streams API."
        />
        <FeatureCard
          icon={<Award className="text-primary-600" size={32} />}
          title="Interactive MCQs"
          description="Test your knowledge with 25 curated MCQs per topic, each with detailed explanations."
        />
        <FeatureCard
          icon={<Code className="text-primary-600" size={32} />}
          title="Coding Playground"
          description="Write and test Java snippets in our integrated playground to solidify your understanding."
        />
      </div>
    </div>
  );
};

const FeatureCard = ({ icon, title, description }) => (
  <div className="card flex flex-col items-center text-center space-y-4">
    <div className="p-3 bg-primary-50 dark:bg-primary-900/30 rounded-full">
      {icon}
    </div>
    <h3 className="text-xl font-bold">{title}</h3>
    <p className="text-slate-600 dark:text-slate-400">{description}</p>
  </div>
);

export default Home;
